selector_to_html = {"a[href=\"user-guide.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">User Guide<a class=\"headerlink\" href=\"#user-guide\" title=\"Link to this heading\">#</a></h1><p>This guide covers how to configure FlagScale and run training, inference, serving, and reinforcement learning tasks.</p>", "a[href=\"#getting-started\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Getting Started<a class=\"headerlink\" href=\"#getting-started\" title=\"Link to this heading\">#</a></h1><h2>Overview<a class=\"headerlink\" href=\"#overview\" title=\"Link to this heading\">#</a></h2><p>FlagScale leverages <a class=\"reference external\" href=\"https://github.com/facebookresearch/hydra\">Hydra</a> for configuration management. The configurations are organized into two levels: an outer experiment-level YAML file and an inner task-level YAML file.</p>", "a[href=\"user-guide.html#step-2-run-tasks\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Step 2\uff1a Run tasks<a class=\"headerlink\" href=\"#step-2-run-tasks\" title=\"Link to this heading\">#</a></h2><p>FlagScale provides a unified runner for various tasks, including training, inference, reinforcement learning, and serving. Simply specify the configuration file to run the task with a single <code class=\"docutils literal notranslate\"><span class=\"pre\">flagscale</span></code> command. The runner will automatically load the configurations and execute the task. The following sections demonstrate how to run a distributed training task.</p>", "a[href=\"requirements.html#supported-models\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Supported models<a class=\"headerlink\" href=\"#supported-models\" title=\"Link to this heading\">#</a></h2><h3>Training<a class=\"headerlink\" href=\"#training\" title=\"Link to this heading\">#</a></h3>", "a[href=\"multi-platform-training.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Multi-Platform Training and Testing<a class=\"headerlink\" href=\"#multi-platform-training-and-testing\" title=\"Link to this heading\">#</a></h1><p>FlagScale has no hardware requirements of its own \u2014 it orchestrates training through the FlagOS plugins. This guide shows how to drive an end-to-end training job on four non-NVIDIA platforms (MetaX, Hygon, Ascend, T-Head PPU) with the plugin stack underneath.</p><p>Platform-specific plugin installation is documented in the plugin guides:</p>", "a[href=\"install.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Install FlagScale<a class=\"headerlink\" href=\"#install-flagscale\" title=\"Link to this heading\">#</a></h1><p>Read <a class=\"reference internal\" href=\"requirements.html\"><span class=\"std std-doc\">Requirements</span></a> before proceeding.</p>", "a[href=\"requirements.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Requirements<a class=\"headerlink\" href=\"#requirements\" title=\"Link to this heading\">#</a></h1><p>This section includes information about the hardware platforms and models.</p>", "a[href=\"install.html#setup\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Setup<a class=\"headerlink\" href=\"#setup\" title=\"Link to this heading\">#</a></h2><h3>1. Select the image<a class=\"headerlink\" href=\"#select-the-image\" title=\"Link to this heading\">#</a></h3><p>FlagScale is installed from a pre-built Docker image. The supported versions and hardware platforms are listed in <a class=\"reference internal\" href=\"requirements.html\"><span class=\"std std-doc\">Requirements</span></a>.</p><p>Go to the <a class=\"reference external\" href=\"https://flagos.io/Home\">FlagOS main page</a>, click <strong>Download</strong> in the middle of the page, and select the Docker image for your hardware and workload:</p>", "a[href=\"#overview\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Overview<a class=\"headerlink\" href=\"#overview\" title=\"Link to this heading\">#</a></h2><p>FlagScale leverages <a class=\"reference external\" href=\"https://github.com/facebookresearch/hydra\">Hydra</a> for configuration management. The configurations are organized into two levels: an outer experiment-level YAML file and an inner task-level YAML file.</p>", "a[href=\"user-guide.html#step-1-configure-yaml-files\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Step 1: Configure YAML files<a class=\"headerlink\" href=\"#step-1-configure-yaml-files\" title=\"Link to this heading\">#</a></h2><p>FlagScale uses <a class=\"reference external\" href=\"https://hydra.cc/\">Hydra</a> for configuration management. Every task is driven by two YAML files that work together: an experiment-level file and a task-level file, both in the <code class=\"docutils literal notranslate\"><span class=\"pre\">examples/</span></code> directory. Before running the task, you need to configure these files first.</p>", "a[href=\"requirements.html#hardware-platforms\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Hardware platforms<a class=\"headerlink\" href=\"#hardware-platforms\" title=\"Link to this heading\">#</a></h2><p>FlagScale is designed to work collaboratively with FlagOS plugins. While FlagScale itself has no hardware platform requirements, you should review the hardware requirements of the specific FlagOS plugins you intend to use. For more information, see <a class=\"reference external\" href=\"https://github.com/flagos-ai/Megatron-LM-FL\">Megatron-LM-FL</a>, <a class=\"reference external\" href=\"https://github.com/flagos-ai/TransformerEngine-FL\">TransformerEngine-FL</a>, <a class=\"reference external\" href=\"https://github.com/flagos-ai/verl-FL\">VeRL-FL</a>, and <a class=\"reference external\" href=\"https://github.com/flagos-ai/vllm-plugin-FL\">vllm-plugin-FL</a>.</p><p>Training has been validated end to end on the following platforms together with Megatron-LM-FL and TransformerEngine-FL:</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
